void corporatePlanNeedsAKnownCompanyCode() {
    assertEquals(ErrorCode.INVALID_REQUEST,
            errorOf(() -> service.create(stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.CORPORATE))));
    assertEquals(ErrorCode.INVALID_REQUEST,
            errorOf(() -> service.create(stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.CORPORATE, "OUTRA"))));

    Reservation reservation = service.create(stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.CORPORATE, "TECNOSUL"));
    assertEquals(new BigDecimal("686.22"), reservation.price().total());
}

